SELECT CASE WHEN salary >= 151000 THEN 'high' WHEN salary >= 55000 THEN 'mid' ELSE 'low' END AS salary_bucket, SUM(CASE WHEN job_title = 'Designer' THEN salary ELSE 0 END) AS designer_salary, COUNT(CASE WHEN job_title = 'Intern' THEN 1 END) AS intern_count, MAX(hire_date) AS last_hire_date FROM employees WHERE manager_id IN (13, 14, 23) AND (UPPER(TRIM(email)) = 'KANYA@MAIL.CO.TH' OR LENGTH(email) >= 14) GROUP BY CASE WHEN salary >= 151000 THEN 'high' WHEN salary >= 55000 THEN 'mid' ELSE 'low' END
